mapper.select:
SELECT FROM () t
t.offering_status='active' AND t.publication_state='published' AND t.assignment_state IN ('NOT_STARTED','IN_PROGRESS') t.assignment_state IN ('SUBMITTED','REVIEWED')
ORDER BY t.due_at,t.id LIMIT #{size} OFFSET #{offset}

SELECT s.id,s.assignment_id,s.offering_id,s.attempt_no AS attempt_number,s.workspace_revision,s.submitted_at,s.is_late AS late,CASE WHEN s.is_current=0 THEN 1 ELSE 0 END AS superseded,
CASE WHEN f.status='published' THEN 'published' ELSE 'none' END AS feedback_status
FROM submissions s LEFT JOIN feedback f ON f.submission_id=s.id
WHERE s.assignment_id=#{assignmentId} AND s.student_id=#{studentId}
ORDER BY s.attempt_no DESC LIMIT #{size} OFFSET #{offset}

SELECT id,offering_id,chapter_id,title,description,estimated_minutes,type,status,is_required,due_at,late_until,allow_resubmit,max_attempts,max_score,content_version,current_ai_policy_id,published_at,created_by,created_at,updated_at
FROM assignments WHERE offering_id=#{offeringId}
AND status=#{publicationState}
ORDER BY created_at DESC,id DESC LIMIT #{size} OFFSET #{offset}

mapper.sql:
WHERE n.recipient_id=#{recipientId}
AND n.related_offering_id=#{offeringId}
AND n.type=#{type}

FROM course_offerings o JOIN courses c ON c.id=o.course_id JOIN terms t ON t.id=o.term_id
JOIN offering_members m ON m.offering_id=o.id
WHERE m.user_id=#{studentId} AND m.role='student' AND m.status='active' AND o.status='active' AND o.term_id=#{termId}

mapper.select:
SELECT o.id AS offering_id,o.course_id,o.title,c.mark,o.group_name,o.term_id,t.label AS term_label,o.status,o.progress_unit,
m.id AS member_id,m.last_studied_at,m.last_chapter_id

ORDER BY (m.last_studied_at IS NULL),m.last_studied_at DESC,o.created_at DESC,o.id DESC LIMIT #{limit}

SELECT COUNT(DISTINCT f.id) FROM notifications n
JOIN feedback f ON f.id=n.related_feedback_id AND f.status='published' AND f.student_id=n.recipient_id
WHERE n.recipient_id=#{recipientId} AND n.type='feedback_published' AND n.is_read=0 AND f.offering_id=#{offeringId}

mapper.sql:
FROM feedback f
JOIN course_offerings o ON o.id=f.offering_id
JOIN offering_members m ON m.offering_id=f.offering_id AND m.user_id=f.student_id AND m.role='student' AND m.status='active'
WHERE f.student_id=#{studentId} AND f.status='published'
AND f.offering_id=#{offeringId}
AND o.term_id=#{termId}

mapper.update:
UPDATE notifications SET is_read=1,read_at=#{readAt,typeHandler=com.learningplatform.common.mybatis.UtcInstantTypeHandler}
WHERE recipient_id=#{recipientId} AND is_read=0
AND related_offering_id=#{offeringId}
AND type=#{type}
